"use strict";exports.qsParse=function(e){const n={},o=String(e||"").replace(/^\?/,"");if(!o)return n;for(const t of o.split("&")){if(!t)continue;const e=t.indexOf("="),o=e>=0?decodeURIComponent(t.slice(0,e)):decodeURIComponent(t),c=e>=0?decodeURIComponent(t.slice(e+1)):"";n[o]=c}return n},exports.qsStringify=function(e){return e?Object.keys(e).map(n=>`${encodeURIComponent(n)}=${encodeURIComponent(null==e[n]?"":e[n])}`).join("&"):""};
